#pragma once

/*
 * BootLogoBitmap.h
 *
 * Auto-generated 1-bit-per-pixel bitmap mask for the boot splash logo.
 * Generated from the source artwork by thresholding to black/white and
 * downscaling with a Lanczos filter, so it stays crisp at boot-screen size.
 *
 * Format:
 *   - 1 bpp, MSB-first, each row padded up to a whole byte
 *     (BOOT_LOGO_BYTES_PER_ROW = ceil(BOOT_LOGO_WIDTH / 8))
 *   - A set bit (1) means "this pixel belongs to the logo glyph"
 *   - Stored in PROGMEM; must be read with pgm_read_byte()
 *
 * Do not hand-edit this file - regenerate it if the source artwork changes.
 */

